using Json=nlohmann::json;
using namespace scratcher::accel;
namespace {
using Clock=std::chrono::steady_clock;
double ms(Clock::time_point at){return std::chrono::duration<double,std::milli>(Clock::now()-at).count();}
uint64_t number(const std::string& value){size_t used=0;auto n=std::stoull(value,&used,0);if(used!=value.size()||value.empty()||value[0]=='-')throw std::runtime_error("Invalid unsigned integer");return n;}
struct Options {uint32_t candidates=32768,queries=64,k=8,repeats=5,workers=8;uint64_t seed=0x53435241,memory=256ULL*1024*1024;std::string fingerprints;};
Options parse(int argc,char** argv){Options o;for(int n=1;n<argc;n+=2){if(n+1==argc)throw std::runtime_error("Each argument requires a value");std::string key=argv[n],value=argv[n+1];if(key=="--fingerprints"){o.fingerprints=value;continue;}auto v=number(value);auto u32=[&](){if(v>UINT32_MAX)throw std::runtime_error("Integer exceeds uint32");return static_cast<uint32_t>(v);};if(key=="--candidates")o.candidates=u32();else if(key=="--queries")o.queries=u32();else if(key=="--k")o.k=u32();else if(key=="--repeats")o.repeats=u32();else if(key=="--workers")o.workers=u32();else if(key=="--seed")o.seed=v;else if(key=="--gpu-memory-mib"){if(v>256)throw std::runtime_error("Device memory cap exceeds 256 MiB");o.memory=v*1024*1024;}else throw std::runtime_error("Unknown argument: "+key);}
 if(!o.candidates||o.candidates>1000000||!o.queries||o.queries>1024||!o.k||o.k>32||!o.repeats||o.repeats>100||!o.workers||o.workers>32||!o.memory)throw std::runtime_error("Argument outside supported benchmark bounds");return o;}
uint64_t checksum(const std::vector<Fingerprint>& values){uint64_t h=14695981039346656037ULL;for(auto& f:values)for(auto word:f)for(unsigned b=0;b<8;++b){h^=(word>>(b*8))&255;h*=1099511628211ULL;}return h;}
uint64_t checksum(const std::vector<std::vector<Neighbor>>& values){uint64_t h=14695981039346656037ULL;for(auto& row:values)for(auto n:row){h^=(uint64_t(n.distance)<<32)|n.index;h*=1099511628211ULL;}return h;}
Fingerprint fingerprint(const Json& input){auto value=input.is_object()?input.at(input.contains("fingerprint_256")?"fingerprint_256":"fingerprint"):input;if(value.is_string()){auto text=value.get<std::string>();if(text.starts_with("0x"))text=text.substr(2);if(text.size()!=64)throw std::runtime_error("Fingerprint string must contain 64 hex digits");Fingerprint f{};for(size_t n=0;n<4;++n){size_t used=0;f[n]=std::stoull(text.substr(n*16,16),&used,16);if(used!=16)throw std::runtime_error("Invalid fingerprint hex string");}return f;}if(!value.is_array()||value.size()!=4)throw std::runtime_error("Fingerprint must have four uint64 words");Fingerprint f{};for(size_t n=0;n<4;++n){if(value[n].is_string())f[n]=number(value[n].get<std::string>());else if(value[n].is_number_unsigned()||(value[n].is_number_integer()&&value[n].get<int64_t>()>=0))f[n]=value[n].get<uint64_t>();else throw std::runtime_error("Invalid fingerprint word");}return f;}
std::vector<Fingerprint> load(const std::string& path){std::ifstream source(path,std::ios::binary);if(!source)throw std::runtime_error("Cannot open fingerprint JSON");source.seekg(0,std::ios::end);if(source.tellg()>64*1024*1024)throw std::runtime_error("Fingerprint JSON exceeds 64 MiB");source.seekg(0);Json input;source>>input;const Json* rows=&input;if(input.is_object()){if(input.contains("items"))rows=&input["items"];else if(input.contains("fingerprints"))rows=&input["fingerprints"];else throw std::runtime_error("Fingerprint object must contain items or fingerprints");}if(!rows->is_array()||rows->empty()||rows->size()>1000000)throw std::runtime_error("Invalid fingerprint corpus size");std::vector<Fingerprint> result;result.reserve(rows->size());for(const auto& row:*rows)result.push_back(fingerprint(row));return result;}
Json timing(const Timings& t){return {{"setup_ms",t.setup_ms},{"corpus_upload_ms",t.corpus_upload_ms},{"query_upload_ms",t.query_upload_ms},{"kernel_ms",t.kernel_ms},{"download_ms",t.download_ms},{"cpu_ms",t.cpu_ms},{"calibration_ms",t.calibration_ms},{"end_to_end_ms",t.end_to_end_ms}};}
Json trial(const SearchResult& r,double wall,uint64_t pairs){auto components=timing(r.timings);if(r.backend!="cuda")for(const char* key:{"setup_ms","corpus_upload_ms","query_upload_ms","kernel_ms","download_ms"})components[key]=nullptr;return {{"backend",r.backend},{"fallback_reason",r.fallback_reason},{"wall_ms",wall},{"timings",components},{"raw_library_timings",timing(r.timings)},{"cpu_workers",r.cpu_workers},{"device_bytes",r.device_bytes},{"kernel_driver_attributes",{{"distance_local_bytes_per_thread",r.backend=="cuda"?Json(r.distance_kernel_local_bytes):Json(nullptr)},{"merge_local_bytes_per_thread",r.backend=="cuda"?Json(r.merge_kernel_local_bytes):Json(nullptr)},{"distance_registers_per_thread",r.backend=="cuda"?Json(r.distance_kernel_registers):Json(nullptr)},{"merge_registers_per_thread",r.backend=="cuda"?Json(r.merge_kernel_registers):Json(nullptr)},{"measurement","CUDA driver compiled-function attributes; not dynamic instruction, spill, occupancy or profiler counters"}}},{"resident_corpus_cache_hit",r.cache_hit},{"neighbor_checksum_fnv1a64",std::to_string(checksum(r.neighbors))},{"comparison_pairs_per_second",wall>0?pairs*1000.0/wall:0.0}};}
Json stats(std::vector<double> values){if(values.empty())return nullptr;std::sort(values.begin(),values.end());auto mean=std::accumulate(values.begin(),values.end(),0.0)/values.size();double variance=0;for(auto v:values)variance+=(v-mean)*(v-mean);variance/=values.size();auto middle=values.size()/2;return {{"count",values.size()},{"median",values.size()%2?values[middle]:(values[middle-1]+values[middle])/2},{"p95",values[static_cast<size_t>(std::ceil(values.size()*.95))-1]},{"mean",mean},{"population_variance",variance},{"min",values.front()},{"max",values.back()}};}
Json aggregate(const Json& trials){Json result;std::vector<double> walls;for(const auto& row:trials)walls.push_back(row.at("wall_ms"));result["wall_ms"]=stats(walls);for(const char* key:{"setup_ms","corpus_upload_ms","query_upload_ms","kernel_ms","download_ms","cpu_ms","end_to_end_ms"}){std::vector<double> times;for(const auto& row:trials)if(row.at("timings").at(key).is_number())times.push_back(row.at("timings").at(key));result["timings"][key]=stats(times);}return result;}
}
int main(int argc,char** argv){try{auto o=parse(argc,argv);std::mt19937_64 random(o.seed);std::vector<Fingerprint> corpus;bool synthetic=o.fingerprints.empty();if(synthetic){corpus.resize(o.candidates);for(auto& row:corpus)for(auto& word:row)word=random();for(size_t n=0;n<std::min<size_t>(16,corpus.size());++n)corpus[n]={0,0,0,0};}else corpus=load(o.fingerprints);if(uint64_t(corpus.size())*o.queries>128ULL*1024*1024)throw std::runtime_error("Benchmark exceeds 128 Mi comparison pairs");auto corpusHash=checksum(corpus);std::vector<Fingerprint> queries(o.queries);for(size_t n=0;n<queries.size();++n){if(!synthetic||n%2==0)queries[n]=corpus[(n*7919)%corpus.size()];else for(auto& word:queries[n])word=random();}queries[0]=corpus[0];auto queryHash=checksum(queries);auto pairs=uint64_t(corpus.size())*queries.size();
 auto construct=Clock::now();Matcher cpu(corpus,o.workers,o.memory);double cpuConstruct=ms(construct);construct=Clock::now();Matcher cuda(corpus,o.workers,o.memory);double cudaConstruct=ms(construct);
 // The first forced GPU request precedes probeGpu(), which otherwise creates a
 // context and warms the driver. CPU reference is the same optimized library.
 auto start=Clock::now();auto coldGpu=cuda.search(queries,o.k,Mode::Cuda);double coldGpuWall=ms(start);start=Clock::now();auto coldCpu=cpu.search(queries,o.k,Mode::Cpu);double coldCpuWall=ms(start);bool coldEqual=coldCpu.neighbors==coldGpu.neighbors,allEqual=coldEqual;Json cpuRows=Json::array(),gpuRows=Json::array();bool allCuda=coldGpu.backend=="cuda";for(uint32_t repeat=0;repeat<o.repeats;++repeat){SearchResult a,b;double aw=0,bw=0;auto cpuRun=[&](){auto began=Clock::now();a=cpu.search(queries,o.k,Mode::Cpu);aw=ms(began);};auto gpuRun=[&](){auto began=Clock::now();b=cuda.search(queries,o.k,Mode::Cuda);bw=ms(began);};if(repeat%2){gpuRun();cpuRun();}else{cpuRun();gpuRun();}bool equal=a.neighbors==b.neighbors;allEqual&=equal;allCuda&=b.backend=="cuda";auto ca=trial(a,aw,pairs),cb=trial(b,bw,pairs);ca["repeat"]=repeat;cb["repeat"]=repeat;cb["exact_cpu_neighbors_equal_including_ties"]=equal;cpuRows.push_back(ca);gpuRows.push_back(cb);}
 bool unchanged=checksum(corpus)==corpusHash&&checksum(queries)==queryHash;auto info=probeGpu();auto cold=trial(coldGpu,coldGpuWall,pairs);cold["exact_cpu_neighbors_equal_including_ties"]=coldEqual;Json summary={{"cpu_warm",aggregate(cpuRows)},{"forced_cuda_warm",aggregate(gpuRows)}};if(allCuda&&allEqual){double a=summary["cpu_warm"]["wall_ms"]["median"],b=summary["forced_cuda_warm"]["wall_ms"]["median"];summary["warm_end_to_end_speedup_vs_optimized_cpu"]=a/b;}else summary["warm_end_to_end_speedup_vs_optimized_cpu"]=nullptr;
 Json output={{"benchmark","HyperDecomp exact 256-bit fingerprint top-k"},{"status",!allEqual?"exact_result_mismatch":allCuda?"cuda_measured":"cpu_fallback_no_cuda_measurement"},{"synthetic",synthetic},{"fingerprints_path",o.fingerprints},{"candidates",corpus.size()},{"queries",queries.size()},{"k",std::min<size_t>(o.k,corpus.size())},{"repeats",o.repeats},{"seed",o.seed},{"workers",o.workers},{"hardware_concurrency",std::thread::hardware_concurrency()},{"comparison_pairs_per_search",pairs},{"corpus_bytes",corpus.size()*sizeof(Fingerprint)},{"query_bytes",queries.size()*sizeof(Fingerprint)},{"configured_device_memory_cap_bytes",o.memory},{"corpus_checksum_fnv1a64",std::to_string(corpusHash)},{"query_checksum_fnv1a64",std::to_string(queryHash)},{"input_vectors_unchanged",unchanged},{"every_trial_exactly_equal",allEqual},{"every_forced_cuda_trial_used_cuda",allCuda},{"device",{{"compiled",info.compiled},{"available",info.available},{"name",info.name},{"reason",info.reason},{"total_bytes",info.total_bytes},{"free_bytes_after_trials",info.free_bytes?Json(info.free_bytes):Json(nullptr)},{"compute_major",info.compute_major},{"compute_minor",info.compute_minor}}},{"construction_ms",{{"cpu",cpuConstruct},{"cuda",cudaConstruct}}},{"cold_cpu",trial(coldCpu,coldCpuWall,pairs)},{"cold_forced_cuda",cold},{"warm_cpu_trials",cpuRows},{"warm_forced_cuda_trials",gpuRows},{"summary",summary},{"method","Fresh process first forced CUDA request before GPU probe; retained immutable corpus for warm trials; alternating CPU/CUDA trial ordering. Exact full neighbor vectors and tie ordering checked each trial against optimized multithreaded library CPU. Corpus/query generation and matcher construction excluded from search walls; construction reported separately. CUDA setup includes compiler/context/module when performed; transfers and kernels separately instrumented. Warm query uploads are not omitted. This is fingerprint matching, not full decompilation or analysis."},{"synthetic_queries",synthetic?"Every even query is an exact corpus item; first 16 corpus entries duplicate zero (stable top-k ties); odd queries are deterministic random.":"All queries are deterministic samples of actual exported corpus fingerprints (self matches retained). Original exported corpus is preserved."}};
 std::cout<<output.dump(2)<<'\n';return allEqual&&unchanged?0:2;
 }catch(const std::exception& e){std::cout<<Json{{"status","error"},{"error",e.what()}}.dump()<<'\n';return 1;}}
